head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/g_url_val.js");
scwin.occr_ddtm;
scwin.rel_src_nm;
scwin.log_contn;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.deleteRows = function(obj) {
    for (var i = obj.countrow; i >= 1; i--) {
        if (obj.NameValue(i, "CHECK") == "T") obj.DeleteRow(i);
    }
};
scwin.fn_sys_log_search = function() {
    var url = "/sms.do?method=sysLogSelect&inputMessageId=tbld_sys_log&outputMessageId=tbld_sys_log" + "&SEARCH_DATE=" + edt_search_date.Text + "&SEARCH_VALUE1=" + tbx_search_value1.value;
    dts_sys_log.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_sys_log.reset();
    $c.cm.ShowWin(grd_sys_log);
};
scwin.fn_sys_msg_search = function() {
    var url = "/sms.do?method=sysMsgSelect&inputMessageId=tbld_sys_msg&outputMessageId=tbld_sys_msg" + "&SEARCH_VALUE=" + tbx_search_value2.value;
    dts_sys_msg.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_sys_msg.reset();
};
scwin.fn_msg_rcv_grp_search = function() {
    var url = "/sms.do?method=msgRcvGrpSelect&inputMessageId=tbld_msg_rcv_grp&outputMessageId=tbld_msg_rcv_grp" + "&SEARCH_VALUE=" + tbx_search_value3.value;
    dts_msg_rcv_grp.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_msg_rcv_grp.reset();
};
scwin.fn_rcv_grp_memb_search = function(rcv_grp_id) {
    var url = "/sms.do?method=rcvGrpMembSelect&inputMessageId=tbld_rcv_grp_memb&outputMessageId=tbld_rcv_grp_memb" + "&RCV_GRP_ID=" + rcv_grp_id;
    dts_rcv_grp_memb.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_rcv_grp_memb.reset();
};
scwin.fn_sms_info = async function() {

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    await $c.frame.CreateDialogFrame("ULDMGT42035", "/common/ULDMGT42035.gfm", "시스템 로그 상세", 150, 50, 830, 540, "window");
};
scwin.fn_data_check = function() {
    for (var i = 1; i <= dts_rcv_grp_memb.getTotalRow(); i++) {
        //alert(i+"==>"+dts_rcv_grp_memb.RowStatus(i));
        if (dts_rcv_grp_memb.getRowStatus(i) == 1) {
            var in_val = dts_rcv_grp_memb.getCellData(i, "INTEG_USR_ID");
            var a_len = in_val.length;
            var b_len = in_val.replace(/[^a-z0-9]/gi, '').length;
            if (a_len != b_len || in_val.length <= 0) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_rcv_grp_memb.NameString(i, "INTEG_USR_ID") = in_val.replace(/[^a-z0-9]/gi, '');*/
                X = in_val.replace(/[^a-z0-9]/gi, '');
                alert("영어, 숫자만 입력 가능합니다.");
                return false;
            }
        }
    }
    return true;
};
scwin.gform_onload = function() {
    //	alert('gform.onload');

	//----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(edt_search_date);
    scwin.fn_sys_msg_search();
    scwin.fn_msg_rcv_grp_search();
};
scwin.MxGrid_3_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.img_date_cal_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_search_date);
};
scwin.btn_search_1_onclick = function(e) {
    scwin.fn_sys_log_search();
};
scwin.btn_sys_msg_search_onclick = function(e) {
    scwin.fn_sys_msg_search();
};
scwin.btn_msg_rcv_grp_search_onclick = function(e) {
    scwin.fn_msg_rcv_grp_search();
};
scwin.btn_add_sys_msg_onclick = function(e) {
    dts_sys_msg.insertRow();
    dts_sys_msg.setCellData(dts_sys_msg.getFocusedRowIndex(), "CHECK", "T");
};
scwin.btn_delete_msg_onclick = function(e) {
    scwin.deleteRows(dts_sys_msg);
};
scwin.btn_save_msg_onclick = function(e) {
    tr_sys_msg.Action = "/sms.do?method=sysMsgSave&inputMessageId=save_sys_msg";
    tr_sys_msg.KeyName = "toinb_dataid4";
    tr_sys_msg.KeyValue = "JSP(I:pInput=dts_sys_msg)";

	//----W-Craft WebSquare 변환 확인: Post----//
    tr_sys_msg.Post();
};
scwin.dts_sys_log_OnLoadCompleted = function(e) {
    //textbox_1.value = "총 " +rowcount+"건";
    $c.cm.CloseWin(rowcount, grd_sys_log);
};
scwin.dts_sys_msg_OnLoadCompleted = function(e) {

};
scwin.dts_msg_rcv_grp_OnLoadCompleted = function(e) {

};
scwin.dts_rcv_grp_memb_OnLoadCompleted = function(e) {

};
scwin.btn_msg_rcv_grp_delete_onclick = function(e) {
    scwin.deleteRows(dts_msg_rcv_grp);
};
scwin.btn_msg_rcv_grp_save_onclick = function(e) {
    tr_msg_rcv_grp.Action = "/sms.do?method=msgRcvGrpSave&inputMessageId=msg_rcv_grp_save";
    tr_msg_rcv_grp.KeyName = "toinb_dataid4";
    tr_msg_rcv_grp.KeyValue = "JSP(I:pInput=dts_msg_rcv_grp)";

	//----W-Craft WebSquare 변환 확인: Post----//
    tr_msg_rcv_grp.Post();
};
scwin.btn_msg_rcv_grp_add_onclick = function(e) {
    dts_msg_rcv_grp.insertRow();
    dts_msg_rcv_grp.setCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "CHECK", "T");
};
scwin.btn_rcv_grp_memb_add_onclick = function(e) {
    if (dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID") != "") {
        dts_rcv_grp_memb.insertRow();
        dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "CHECK", "T");
        dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "RCV_GRP_ID", dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
    } else {
        alert("수신그룹관리를 선택하여 주십시요.");
    }
    //dts_rcv_grp_memb.AddRow();

    //dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "CHECK") = "T";

    //dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "RCV_GRP_ID") = dts_msg_rcv_grp.NameValue(dts_msg_rcv_grp.RowPosition, "RCV_GRP_ID") ;	

};
scwin.btn_rcv_grp_memb_save_onclick = function(e) {
    if (scwin.fn_data_check()) {
        tr_rcv_grp_memb.Action = "/sms.do?method=rcvGrpMembSave&inputMessageId=rcv_grp_memb_save";
        tr_rcv_grp_memb.KeyName = "toinb_dataid4";
        tr_rcv_grp_memb.KeyValue = "JSP(I:pInput=dts_rcv_grp_memb)";

	//----W-Craft WebSquare 변환 확인: Post----//
        tr_rcv_grp_memb.Post();
    }
};
scwin.MxGrid_3_OnClick = function(row, colid) {
    scwin.fn_rcv_grp_memb_search(dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
};
scwin.btn_rcv_grp_memb_delete_onclick = function(e) {
    scwin.deleteRows(dts_rcv_grp_memb);
};
scwin.tr_sys_msg_OnSuccess = function(e) {
    alert('저장하였습니다');
    scwin.fn_sys_msg_search();
};
scwin.tr_sys_msg_OnFail = function(e) {
    alert('저장을 실패했습니다');
};
scwin.tr_msg_rcv_grp_OnSuccess = function(e) {
    alert('저장하였습니다');
    scwin.fn_msg_rcv_grp_search();
};
scwin.tr_msg_rcv_grp_OnFail = function(e) {
    alert('저장을 실패했습니다');
};
scwin.tr_rcv_grp_memb_OnSuccess = function(e) {
    alert('저장하였습니다');
    scwin.fn_rcv_grp_memb_search(dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
};
scwin.tr_rcv_grp_memb_OnFail = function(e) {
    alert('저장을 실패했습니다');
};
scwin.grd_sys_log_OnDblClick = function(row, colid) {
    scwin.occr_ddtm = dts_sys_log.getCellData(row, "OCCR_DDTM");
    scwin.rel_src_nm = dts_sys_log.getCellData(row, "REL_SRC_NM");
    scwin.log_contn = dts_sys_log.getCellData(row, "LOG_CONTN");
    scwin.fn_sms_info();
};
